// create a permanent record keyed to a person who does not exist here, while the
// attempt still has to be counted for stuffing detection — which is what
// email_index carries.
func (q *Queries) RecordLoginAttempt(ctx context.Context, arg RecordLoginAttemptParams) error {
	_, err := q.db.Exec(ctx, RecordLoginAttempt,
		arg.SubjectID,
		arg.EmailIndex,
		arg.Succeeded,
		arg.Reason,
		arg.Methods,
		arg.Aal,
		arg.DeviceID,
		arg.OccurredAt,
	)
	return err
}

const ReleaseUserEmailIndex = `-- name: ReleaseUserEmailIndex :exec
UPDATE user_view
SET email_released_at = $3
WHERE subject_id = $1 AND email_index = $2 AND email_released_at IS NULL
`

type ReleaseUserEmailIndexParams struct {
	SubjectID       string
	EmailIndex      string
	EmailReleasedAt pgtype.Timestamptz
}

// Applied from EmailReleased: this account no longer holds this address.
//
// The row is MARKED, never deleted and never blanked. A release does not delete
// the account — the squatter's Pending account survives its own lapsed claim by
// design (identity.md §4.3) — so the account projection must be able to say
// "this account USED to hold this address, another holds it now". That sentence
// is what the partial unique index in migration 00014 makes representable, and
// without it the next registration for the address stops the projector on a
// duplicate key and the table stops being rebuildable from position zero.
//
// Guarded on BOTH subject_id and email_index. On subject_id because a release
// names the holder whose claim ended, and applying it to whoever holds the
// address now would retire the live row and hand the index to nobody. On
// email_index because an account that has since moved to another address must
// not be marked as having released the one it currently holds.
//
// That second guard was written while it was redundant, against the day an
// email-change flow existed. It exists now (identity.md §12), and the guard is
// what it was written for: the old address of a completed change is released by
// the sweep when its revert window closes, LONG after the account moved on, and
// an unguarded statement would then stamp `email_released_at` on an account that
// holds a perfectly good address — reporting it as holding none.
//
// `email_released_at IS NULL` makes it idempotent: replayed, the second
// application matches no row and the first timestamp stands. Re-applying with
// the same timestamp would also be harmless; keeping the first one means the
// column answers "when did this account lose the address" rather than "when was
// this event last replayed".
func (q *Queries) ReleaseUserEmailIndex(ctx context.Context, arg ReleaseUserEmailIndexParams) error {
	_, err := q.db.Exec(ctx, ReleaseUserEmailIndex, arg.SubjectID, arg.EmailIndex, arg.EmailReleasedAt)
	return err
}

const RevokeAllSessions = `-- name: RevokeAllSessions :execrows
UPDATE session_view SET revoked_at = now()
WHERE subject_id = $1 AND revoked_at IS NULL AND session_id <> $2
`

type RevokeAllSessionsParams struct {
	SubjectID string
	SessionID string
}

// Revoke every live session for a subject, optionally sparing one.
//
// The exception is "sign out everywhere else", which must not sign the caller
// out of the device they are asking from. Passing the empty string spares
// nothing, which is what a password reset needs.
func (q *Queries) RevokeAllSessions(ctx context.Context, arg RevokeAllSessionsParams) (int64, error) {
	result, err := q.db.Exec(ctx, RevokeAllSessions, arg.SubjectID, arg.SessionID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

